// Isolated native squad and construction-connectivity engine diagnostics.
#define Generate_Mission_Starts SAM_Regression
#include "../tests/samblast_engine.cpp"
#undef Generate_Mission_Starts
#include "campaignformation.h"
#include "campaignexpansion.h"
#include "campaignwaves.h"
static CELL middle;
static void Tile(int x,int y,bool open){CELL c=XY_Cell(x,y);if(!Map.In_Radar(c))return;auto& m=Map[c];m.TType=TEMPLATE_CLEAR1;m.TIcon=0;m.Overlay=open?OVERLAY_NONE:OVERLAY_BRICK_WALL;m.OverlayData=0;m.Owner=HOUSE_NONE;m.Recalc_Attributes();}
static void Setup(const std::string& dir){Reset(dir);Campaign_Formation_Reset();middle=Center();for(int i=Terrains.Count()-1;i>=0;--i)Terrains.Ptr(i)->Limbo();for(int y=Map.MapCellY;y<Map.MapCellY+Map.MapCellHeight;++y)for(int x=Map.MapCellX;x<Map.MapCellX+Map.MapCellWidth;++x)Tile(x,y,true);auto enemy=HouseClass::As_Pointer(HOUSE_BAD);enemy->IsActive=true;enemy->IsDefeated=false;}
static UnitClass* TargetUnit(){auto t=new UnitClass(UNIT_MTANK,HOUSE_GOOD);Check("place player formation target",t->Unlimbo(Cell_Coord(XY_Cell(Map.MapCellX+Map.MapCellWidth-4,Cell_Y(middle))),DIR_N));t->Strength=30000;t->Assign_Mission(MISSION_SLEEP);t->Commence();return t;}
static FootClass* Combat(int index,bool infantry=false){FootClass* f=infantry?static_cast<FootClass*>(new InfantryClass(INFANTRY_E1,HOUSE_BAD)):static_cast<FootClass*>(new UnitClass(UNIT_LTANK,HOUSE_BAD));Check("place native formation member",f->Unlimbo(Cell_Coord(XY_Cell(Map.MapCellX+4+(index%4)*2,Cell_Y(middle)+(index/4)*2-3)),DIR_E));f->Assign_Mission(MISSION_GUARD);f->Commence();Campaign_Enemies_Mark_Extra(f);return f;}
static void Group(const std::string& dir,bool save){Setup(dir);auto target=TargetUnit();std::vector<TARGET> ids;for(int i=0;i<8;++i){auto f=Combat(i,i>=4);ids.push_back(f->As_Target());Campaign_Formation_Recruit(f);}std::set<TARGET> slots;bool gathering=true;for(auto id:ids){auto f=static_cast<FootClass*>(As_Techno(id));gathering&=Campaign_Formation_Holding(f)&&f->Mission==MISSION_MOVE&&Target_Legal(f->NavCom);slots.insert(f->NavCom);}Check("new enemy troops gather instead of immediately charging in a column",gathering);Check("gathering gives every combatant a separate formation slot",slots.size()==ids.size());auto first=static_cast<FootClass*>(As_Techno(ids[0]));auto nav=first->NavCom;
 if(save){Check("save gathered squad",Save_Game((dir+"/formation.sav").c_str(),"GATHERED SQUAD"));Check("reload gathered squad",Load_Game((dir+"/formation.sav").c_str()));first=static_cast<FootClass*>(As_Techno(ids[0]));target=static_cast<UnitClass*>(As_Techno(target->As_Target()));Check("saved squad preserves membership and slot intent",Campaign_Formation_Holding(first)&&first->NavCom==nav);}
 Frame+=21*TICKS_PER_SECOND;Campaign_Formation_AI();slots.clear();bool approaching=true;for(auto id:ids){auto f=static_cast<FootClass*>(As_Techno(id));slots.insert(f->NavCom);approaching&=Campaign_Formation_Holding(f)&&f->Mission==MISSION_MOVE;}Check("bounded gathering advances the whole group on separate approach slots",approaching&&slots.size()>=6);Frame+=26*TICKS_PER_SECOND;Campaign_Formation_AI();bool attacking=true;for(auto id:ids){auto f=static_cast<FootClass*>(As_Techno(id));attacking&=!Campaign_Formation_Holding(f)&&f->Mission==MISSION_HUNT;}Check("bounded approach timeout prevents permanent squad waiting",attacking);
}
static void YieldDuringLaunch(const std::string& dir){Setup(dir);TargetUnit();auto f=Combat(0);Campaign_Formation_Recruit(f);Frame+=21*TICKS_PER_SECOND;Campaign_Formation_AI();auto oldMission=f->Mission;auto oldNav=f->NavCom;f->Assign_Mission(MISSION_MOVE);f->Commence();f->Assign_Destination(::As_Target(XY_Cell(Map.MapCellX+6,Cell_Y(middle)-4)));f->SuspendedMission=oldMission;f->SuspendedNavCom=oldNav;f->SuspendedTarCom=TARGET_NONE;Frame+=26*TICKS_PER_SECOND;Campaign_Formation_AI();Check("formation launch leaves traffic's suspended order intact",f->SuspendedMission!=MISSION_NONE);f->Restore_Mission();f->Commence();Campaign_Formation_AI();Check("member finishing traffic yield rejoins its already launched squad",f->Mission==MISSION_HUNT&&!Campaign_Formation_Holding(f));}
static void LossBeforeLaunch(const std::string& dir){Setup(dir);TargetUnit();auto armor=Combat(0),infantry=Combat(1,true),lost=Combat(2,true);Campaign_Formation_Recruit(armor);Campaign_Formation_Recruit(lost);Campaign_Formation_Recruit(infantry);delete lost;Frame+=21*TICKS_PER_SECOND;Campaign_Formation_AI();Check("casualties before deployment do not break mixed-armor formation ordering",armor->Mission==MISSION_MOVE&&infantry->Mission==MISSION_MOVE&&armor->NavCom!=infantry->NavCom);}
static void DisconnectedProduction(const std::string& dir){Setup(dir);TargetUnit();int wallX=Cell_X(middle);for(int y=Map.MapCellY;y<Map.MapCellY+Map.MapCellHeight;++y)Tile(wallX,y,false);auto a=new UnitClass(UNIT_LTANK,HOUSE_BAD),b=new UnitClass(UNIT_LTANK,HOUSE_BAD);Check("place troops in nearby disconnected land regions",a->Unlimbo(Cell_Coord(XY_Cell(wallX-3,Cell_Y(middle))),DIR_E)&&b->Unlimbo(Cell_Coord(XY_Cell(wallX+3,Cell_Y(middle))),DIR_W));a->Assign_Mission(MISSION_GUARD);a->Commence();b->Assign_Mission(MISSION_GUARD);b->Commence();Campaign_Formation_Recruit(a);Campaign_Formation_Recruit(b);Check("nearby isolated factories never share unreachable rally positions",Campaign_Formation_Holding(a)&&Campaign_Formation_Holding(b)&&Cell_X(As_Cell(a->NavCom))<wallX&&Cell_X(As_Cell(b->NavCom))>wallX);}
static void NativeTravel(const std::string& dir){Setup(dir);auto target=TargetUnit();std::vector<TARGET> ids;for(int i=0;i<6;++i){auto f=Combat(i,i>=3);ids.push_back(f->As_Target());Campaign_Formation_Recruit(f);}int startX=Map.MapCellX+4;for(int tick=0;tick<2500;++tick){++Frame;if(Frame%15==0)Campaign_Formation_AI();for(auto id:ids){auto t=As_Techno(id);if(!t||t->Strength<=0)continue;if(t->What_Am_I()==RTTI_UNIT)static_cast<UnitClass*>(t)->AI();else static_cast<InfantryClass*>(t)->AI();}if(!Campaign_Formation_Holding(static_cast<FootClass*>(As_Techno(ids[0])))&&Cell_X(Coord_Cell(As_Techno(ids[0])->Coord))>startX+10)break;}int advanced=0;for(auto id:ids){auto f=As_Techno(id);if(f&&Cell_X(Coord_Cell(f->Coord))>startX+8)++advanced;}Check("native units actually leave rally and advance toward the enemy",advanced>=4);}
static void Companions(const std::string& dir){Setup(dir);TargetUnit();auto strip=new BuildingClass(STRUCT_AIRSTRIP,HOUSE_BAD);Put(strip,XY_Cell(Map.MapCellX+4,Cell_Y(middle)));auto h=HouseClass::As_Pointer(HOUSE_BAD);h->Credits=100000;h->Tiberium=0;auto f=new FactoryClass;Check("queue real three-unit formation production",f->Set(UnitTypeClass::As_Reference(UNIT_LTANK),*h)&&f->Start());for(int tick=0;tick<50000&&!f->Has_Completed();++tick){++Frame;f->AI();}Check("formation production finishes and releases",f->Has_Completed()&&strip->Exit_Object(f->Get_Object())==2);f->Completed();delete f;Campaign_Enemies_Apply();Campaign_Formation_AI();std::set<TARGET> slots;int members=0;for(int i=0;i<Units.Count();++i){auto u=Units.Ptr(i);if(!u->IsInLimbo&&u->House==h){++members;Check("all three paid-production companions join the squad",Campaign_Formation_Holding(u));slots.insert(u->NavCom);}}Check("three companions receive distinct formation destinations",members==3&&slots.size()==3);Campaign_Enemies_Apply();slots.clear();for(int i=0;i<Units.Count();++i){auto u=Units.Ptr(i);if(!u->IsInLimbo&&u->House==h)slots.insert(u->NavCom);}Check("legacy companion synchronization never overwrites formation slots",slots.size()==3);}
static void EmergencyAndRestrictions(const std::string& dir){Setup(dir);auto target=TargetUnit();auto f=Combat(0);auto id=f->As_Target();f->Assign_Mission(MISSION_AMBUSH);f->Commence();Campaign_Formation_Recruit(f);Check("scripted ambush orders are preserved",!Campaign_Formation_Holding(f)&&f->Mission==MISSION_AMBUSH);f->Assign_Mission(MISSION_GUARD);f->Commence();GameToPlay=GAME_SKIRMISH;Campaign_Formation_Recruit(f);Check("skirmish squads remain native",!Campaign_Formation_Holding(f));GameToPlay=GAME_NORMAL;f->House=PlayerPtr;Campaign_Formation_Recruit(f);Check("player combatants are never commandeered into enemy squads",!Campaign_Formation_Holding(f));f->House=HouseClass::As_Pointer(HOUSE_BAD);f->Limbo();Check("place emergency defender near player target",f->Unlimbo(Cell_Coord(XY_Cell(Cell_X(Coord_Cell(target->Coord))-3,Cell_Y(middle))),DIR_E));Campaign_Formation_Recruit(f);Check("nearby danger triggers immediate combat instead of waiting",!Campaign_Formation_Holding(f)&&f->Mission==MISSION_HUNT);delete f;Campaign_Formation_Forget(id);Check("new object in reused slot starts without stale formation intent",!Campaign_Formation_Holding(Combat(0)));}
static void MCVChoke(const std::string& dir){Setup(dir);auto const& yard=BuildingTypeClass::As_Reference(STRUCT_CONST);CELL top=XY_Cell(Cell_X(middle)-1,Cell_Y(middle)-1);int minY=MAP_CELL_H,maxY=0;for(auto p=yard.Occupy_List(true);*p!=REFRESH_EOL;++p){minY=MIN(minY,Cell_Y(top+*p));maxY=MAX(maxY,Cell_Y(top+*p));}for(int y=Map.MapCellY;y<Map.MapCellY+Map.MapCellHeight;++y)for(int x=Map.MapCellX;x<Map.MapCellX+Map.MapCellWidth;++x)Tile(x,y,y>=minY&&y<=maxY);auto mcv=new UnitClass(UNIT_MCV,HOUSE_BAD);Check("place MCV inside a narrow construction-width route",mcv->Unlimbo(Cell_Coord(middle),DIR_SW));mcv->PrimaryFacing=DIR_SW;mcv->Assign_Destination(TARGET_NONE);auto id=mcv->As_Target();bool deployed=mcv->Try_To_Deploy();Check("native enemy MCV deployment refuses to seal the entire corridor",!deployed&&As_Unit(id)&&As_Unit(id)->IsActive);}
static void ConstructionRoutes(const std::string& dir){Setup(dir);int x=Cell_X(middle),y=Cell_Y(middle);auto const& wall=BuildingTypeClass::As_Reference(STRUCT_BRICK_WALL);auto const& turret=BuildingTypeClass::As_Reference(STRUCT_TURRET);Check("open ground permits a building while retaining routes",Campaign_Construction_Preserves_Paths(turret,middle));for(int yy=y-8;yy<=y+8;++yy)for(int xx=x-8;xx<=x+8;++xx)Tile(xx,yy,false);for(int xx=x-8;xx<=x+8;++xx)Tile(xx,y,true);Check("building across a one-cell alley is rejected",!Campaign_Construction_Preserves_Paths(turret,middle));Check("concrete segment closing the last passage is rejected",!Campaign_Construction_Preserves_Paths(wall,middle));for(int xx=x-8;xx<=x+8;++xx)Tile(xx,y+1,true);Check("wall that leaves a real adjacent route is permitted",Campaign_Construction_Preserves_Paths(wall,middle));}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);Group(dir,false);Group(dir,true);YieldDuringLaunch(dir);LossBeforeLaunch(dir);DisconnectedProduction(dir);NativeTravel(dir);Companions(dir);EmergencyAndRestrictions(dir);MCVChoke(dir);ConstructionRoutes(dir);std::printf("TOTAL FAILURES %d\n",failures);return failures==0;}
